-- 0058_qp_qa_02_glass_control.sql
--
-- QP-QA-02 การควบคุมการปนเปื้อนทางกายภาพ Rev.02 read against the system.
--
-- Two columns and three findings. The columns close the gap between what the
-- procedure requires at a breakage and what the module could record; the
-- findings are what reading the document turned up and cannot be fixed here.

-- ── the breakage record ─────────────────────────────────────────────────────
-- QP-QA-02 ends its breakage procedure with reconstruction: account for every
-- fragment of what broke before the line is allowed to restart. That is the
-- step the whole procedure turns on — stopping the line and sweeping up are
-- containment, but only reconstruction answers "is any of it still in the
-- product". The module had nowhere to record it, so a breakage record could be
-- filed complete with the one thing that decides the outcome unstated.
ALTER TABLE ghp_glass_control ADD COLUMN reconstruction TEXT;

-- Rev.02's other new rule is that nothing enters the area without a register
-- code: "ห้ามมิให้นำอุปกรณ์ที่ไม่มีรหัสทะเบียน ... เข้ามาใช้งานในพื้นที่โดยเด็ดขาด".
-- A check that does not name which registered item was checked cannot show the
-- register was covered, and cannot show an unregistered item was refused.
ALTER TABLE ghp_glass_control ADD COLUMN registerCode TEXT;

-- ── findings ────────────────────────────────────────────────────────────────
